<template><div ref="root" class="emoji-picker-wrapper"><button type="button" class="emoji-picker-trigger" @click="open=!open">{{t('emojiBtn')}}</button><div v-if="open" class="emoji-picker-overlay" @click="open=false"></div><div v-if="open" class="emoji-picker-panel"><div class="emoji-picker-grid"><button v-for="e in emojis" :key="e.file" type="button" class="emoji-picker-item" :title="e.name" @click="select(e)"><img :src="assetUrl(e.file)" :alt="e.name"></button></div></div></div></template>
<script setup>import {onMounted,onUnmounted,ref} from 'vue';import {useLang} from '../contexts/app';import './EmojiPicker.css';defineProps({});const emit=defineEmits(['select']);const {t}=useLang();const open=ref(false),root=ref(null);const emojis=[['哦哟','哦哟.jpg'],['哭哭','哭哭.jpg'],['喜欢','喜欢.png'],['委屈屈','委屈屈.png'],['帅气','帅气.png'],['平静','平静.png'],['开心','开心.jpg'],['惊恐','惊恐.png'],['惊讶','惊讶.png'],['愤怒','愤怒.png'],['无语','无语.png'],['爱心','爱心.png'],['疑问','疑问.jpg'],['小七-开心','小七-开心.png'],['小七-沉默','小七-沉默.png'],['小七-悲伤','小七-悲伤.png'],['小七-疑问','小七-疑问.png'],['黄符-哭','黄符-哭.png'],['黄符-威胁','黄符-威胁.png'],['黄符-抱抱','黄符-抱抱.png'],['黄符-累趴','黄符-累趴.png'],['绝望的小蛋黄','绝望的小蛋黄.jpg'],['酒哥儿-无奈','酒哥儿-无奈.png'],['酒哥儿-点赞','酒哥儿-点赞.png'],['酒哥儿-送花','酒哥儿-送花.png']].map(([name,file])=>({name,file}));const assetUrl=(file)=>`/assets/images/imgs/${encodeURIComponent(file)}`;const select=e=>{emit('select',`[emoji:${e.file}]`);open.value=false};const outside=e=>{if(root.value&&!root.value.contains(e.target))open.value=false};onMounted(()=>document.addEventListener('mousedown',outside));onUnmounted(()=>document.removeEventListener('mousedown',outside));</script>
